mapper.select:
SELECT CPU_USED_RATE cpuUsedRate,
       END_TIME collectTime
FROM HOUR_CPU
WHERE ASSET_ID = #{assetId}
  AND END_TIME BETWEEN #{startDate} AND #{endDate}
ORDER BY END_TIME

SELECT CPU_USED_RATE cpuUsedRate,
       END_TIME collectDate
FROM HOUR_CPU
WHERE ASSET_ID = #{assetId}
  AND END_TIME >= #{endDate}
ORDER BY collectDate
